by_capture.map:
function(doc) {
  if (doc.doc_type !== "photo_vision_sidecar") return;
  if (!doc.capture_id) return;
  emit(doc.capture_id, {
    photo_id: doc.photo_id || "",
    filename: doc.filename || "",
    source_image_path: doc.source_image_path || "",
    description: doc.description || "",
    summary: doc.summary || "",
    area_guess: doc.area_guess || "",
    qc_category: doc.qc_category || ""
  });
}
